/**
 * Act Service - Action Execution Layer
 *
 * KT NOTE ARCHITECTURE COMPLIANCE:
 *
 * This service implements the final stage of the cognitive loop:
 *   Think → Govern → HITL → ACT → REPEAT
 *
 * Key KT Note Requirements:
 *
 * 1. NO ACTION WITHOUT APPROVAL (Rule 5):
 *    - All execution paths require x-approval-token validation
 *    - Tokens are generated by Govern service after policy checks
 *    - Both action_id (HITL) and action_proposal_id (Think) paths enforced
 *
 * 2. RE-INGESTION THROUGH PIPELINE (§11):
 *    - Action results are sent to PIPELINE service, NOT direct Spine writes
 *    - Results go through the 8-stage normalization before updating truth
 *    - This ensures audit trails, schema validation, and consistency
 *
 * 3. CONNECTOR EXECUTION:
 *    - Approved actions are executed through connector service
 *    - Connector writes to external tools, not directly to Spine
 *    - External tool responses are re-ingested through pipeline
 *
 * ANTI-PATTERNS PREVENTED:
 * - Direct SQL writes to Spine tables (see deprecated execution.ts)
 * - Bypassing approval token validation
 * - Auto-execution without HITL approval
 */

import { Hono } from "hono";
import { cors } from "hono/cors";

type Bindings = {
  // Primary data source (truth database)
  SUPABASE_URL: string;
  SUPABASE_SERVICE_KEY: string;

  // Edge cache (D1) — used for cached projections, idempotency, and sync cursors
  DB: D1Database;

  GOVERN?: Fetcher;
  THINK?: Fetcher;
  STORE?: Fetcher;
  CONNECTOR?: Fetcher;
  PIPELINE?: Fetcher;

  ENVIRONMENT: string;
  SERVICE_SECRET?: string;
};

// ============================================================================
// Supabase Query Helper (Truth Database)
// ============================================================================
async function supabaseQuery(
  url: string,
  key: string,
  table: string,
  query: string
): Promise<any[]> {
  try {
    const res = await fetch(`${url}/rest/v1/${table}?${query}`, {
      headers: {
        apikey: key,
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
      },
    });

    if (!res.ok) {
      console.error(`Supabase query failed: ${res.status} ${res.statusText}`);
      return [];
    }

    return res.json();
  } catch (err: any) {
    console.error(`Supabase fetch error: ${err.message}`);
    return [];
  }
}

const app = new Hono<{ Bindings: Bindings }>();

app.use("*", cors());

app.get("/health", (c) =>
  c.json({
    service: "Act Layer (Agents)",
    status: "operational",
    database: "Supabase (truth) + D1 (edge cache)",
  })
);

/**
 * Execute an Action — MANDATORY APPROVAL CHECK
 * KT NOTE: "No action executes without approval" — enforced at service entry
 *
 * Supports two formats:
 * (1) HITL path: action_id + approval_token from actions table
 * (2) Think path: action_proposal_id + approval_token (Flow C governance)
 */
app.post("/execute", async (c) => {
  const body = await c.req.json().catch(() => ({}));
  const tenantId = c.req.header("x-tenant-id") || (body as any).tenant_id;
  const correlationId = c.req.header("x-correlation-id") || crypto.randomUUID();
  const approvalToken = (body as any).approval_token || c.req.header("x-approval-token");

  // MANDATORY: All execution paths require approval token (KT Note Rule 5)
  if (!approvalToken) {
    return c.json(
      {
        error: "x-approval-token required",
        message: "No action executes without approval (KT Note §Rule 5)",
      },
      403
    );
  }

  if (!tenantId) return c.json({ error: "x-tenant-id required" }, 400);

  const actionId = (body as any).action_id;
  const actionProposalId = (body as any).action_proposal_id;

  try {
    let proposal: any;
    let source: "actions" | "action_proposals";

    // Path 1: HITL — from actions table (workflow handleApproval → ACT_QUEUE)
    if (actionId) {
      const actions = await supabaseQuery(
        c.env.SUPABASE_URL,
        c.env.SUPABASE_SERVICE_KEY,
        "actions",
        `id=eq.${actionId}&tenant_id=eq.${tenantId}`
      );
      const row = actions?.[0];
      if (!row) return c.json({ error: "Action not found" }, 404);
      if (row.status !== "approved") return c.json({ error: "Action not approved" }, 403);
      if (row.approval_token !== approvalToken) {
        return c.json({ error: "Invalid approval token" }, 403);
      }
      proposal = {
        id: row.id,
        action_type: row.action_type || row.type,
        target_tool: row.target_tool || "spine",
        parameters: row.parameters || row.payload || {},
        entity_id: row.payload?.entity_id || row.payload?.spine_id,
        entity_type: row.payload?.entity_type,
      };
      source = "actions";
    }
    // Path 2: Think — from action_proposals table (Flow C)
    else if (actionProposalId) {
      const proposals = await supabaseQuery(
        c.env.SUPABASE_URL,
        c.env.SUPABASE_SERVICE_KEY,
        "action_proposals",
        `id=eq.${actionProposalId}&tenant_id=eq.${tenantId}`
      );
      proposal = proposals?.[0];
      if (!proposal) return c.json({ error: "Action proposal not found in Spine" }, 404);

      // MANDATORY: Validate approval_token for Flow C proposals too
      // Proposal must have been approved via Govern/HITL to have a valid token
      if (proposal.approval_token !== approvalToken) {
        return c.json(
          {
            error: "Invalid approval token",
            message: "Flow C proposals require Govern approval before execution",
          },
          403
        );
      }
      if (proposal.status !== "approved") {
        return c.json(
          {
            error: "Proposal not approved",
            message: "Flow C proposal must be approved via Govern/HITL",
          },
          403
        );
      }
      source = "action_proposals";
    } else {
      return c.json({ error: "action_id or action_proposal_id required" }, 400);
    }

    // 1.5. MANDATORY GOVERNANCE CHECK (Service Binding)
    if (!c.env.GOVERN) {
      return c.json(
        { error: "Governance service unavailable — execution denied (fail-safe)" },
        503
      );
    }

    const govCheck = await c.env.GOVERN.fetch("http://internal/v1/check", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-tenant-id": tenantId,
        "x-user-id": "system-agent",
        "x-correlation-id": correlationId,
        "x-service-auth": c.env.SERVICE_SECRET || "internal-default",
      },
      body: JSON.stringify({
        action_type: proposal.action_type,
        priority: proposal.priority || "medium",
        parameters:
          typeof proposal.parameters === "string"
            ? JSON.parse(proposal.parameters)
            : proposal.parameters,
      }),
    });

    if (govCheck.ok) {
      const checkResult = (await govCheck.json()) as any;
      if (!checkResult.data?.allowed) {
        return c.json(
          {
            error: "Governance Denied",
            reason: checkResult.data?.reason || "Policy violation",
          },
          403
        );
      }
    } else {
      // If governance service is down/failing, we fail-safe (deny) in production
      return c.json({ error: "Governance Check Failed" }, 503);
    }

    const entityId = source === "actions" ? actionId : actionProposalId;

    // 2. Log "Execution Attempt" to Spine
    const runId = crypto.randomUUID();
    try {
      await c.env.DB.prepare(
        `
                INSERT INTO audit_logs (id, tenant_id, actor_id, actor_type, action, entity_type, entity_id, metadata)
                VALUES (?, ?, 'act-engine', 'engine', 'execution_started', ?, ?, ?)
            `
      )
        .bind(
          crypto.randomUUID(),
          tenantId,
          source,
          entityId,
          JSON.stringify({ runId, correlationId })
        )
        .run();
    } catch {
      /* D1 may not have audit_logs; non-blocking */
    }

    // 3. Execute via Connector (real write-back to external tools)
    let executionResult: any = {
      success: true,
      run_id: runId,
      executed_at: new Date().toISOString(),
    };
    const targetTool = proposal.target_tool || proposal.action_type?.split(".")[0];
    const params =
      typeof proposal.parameters === "string"
        ? JSON.parse(proposal.parameters)
        : proposal.parameters || {};

    if (c.env.CONNECTOR && targetTool && targetTool !== "spine") {
      try {
        const connectorRes = await c.env.CONNECTOR.fetch(
          new Request("http://connector/api/v1/connector/execute", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "x-tenant-id": tenantId,
              "x-correlation-id": correlationId,
            },
            body: JSON.stringify({
              provider: targetTool,
              action: proposal.action_type,
              parameters: params,
              entity_id: proposal.entity_id,
            }),
          })
        );

        if (connectorRes.ok) {
          const connResult = (await connectorRes.json()) as any;
          executionResult = { ...executionResult, connector_result: connResult };
        } else {
          executionResult.connector_error = `Connector returned ${connectorRes.status}`;
          executionResult.success = false;
        }
      } catch (connErr: any) {
        console.warn(`[Act] Connector execution failed: ${connErr.message}`);
        executionResult.connector_error = connErr.message;
      }
    }

    // 4. RE-INGESTION: KT Note §11 - "The result is re-ingested through the pipeline"
    // CRITICAL: Action results must go back through the 8-stage pipeline to update Spine.
    // Direct writes to Spine bypass normalization, schema validation, and audit trails.
    if (c.env.PIPELINE && executionResult.success) {
      try {
        await c.env.PIPELINE.fetch(
          new Request("http://pipeline/api/write", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "x-tenant-id": tenantId,
            },
            body: JSON.stringify({
              entity_type: proposal.entity_type || "action_result",
              source: "act-engine",
              data: {
                action_id: entityId,
                action_type: proposal.action_type,
                result: executionResult,
                executed_at: executionResult.executed_at,
              },
            }),
          })
        );
        console.log(`[Act] Re-ingested execution result to pipeline (KT Note §11 REPEAT loop)`);
      } catch (pipeErr: any) {
        console.warn(`[Act] Pipeline re-ingestion failed: ${pipeErr.message}`);
      }
    } else if (!c.env.PIPELINE) {
      console.warn(
        `[Act] PIPELINE service not bound - cannot re-ingest result (KT Note violation)`
      );
    }

    // 5. OUTCOME LEARNING: Send feedback to Think service for cognitive loop completion
    // This enables the AI to learn from action outcomes and refine rules over time
    if (c.env.THINK) {
      try {
        const outcomeFeedback = {
          action_id: entityId,
          proposal_id: actionProposalId,
          tenant_id: tenantId,
          entity_type: proposal.entity_type || "unknown",
          entity_id: proposal.spine_id || proposal.params?.entity_id || "unknown",
          action_type: proposal.action_type || proposal.action_key || "unknown",
          success: executionResult.success,
          outcome_summary: executionResult.success
            ? `Action executed successfully via ${executionResult.connector_used || "unknown"}`
            : `Action failed: ${executionResult.connector_error || "Unknown error"}`,
          error_details: executionResult.connector_error,
          execution_time_ms: Date.now() - new Date(executionResult.executed_at).getTime(),
          correlation_id: correlationId,
          triggered_by_rules: proposal.triggered_by_rules || [], // Rules that triggered this action
        };

        await c.env.THINK.fetch(
          new Request("http://think/v1/outcome/feedback", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "x-tenant-id": tenantId,
              "x-correlation-id": correlationId,
            },
            body: JSON.stringify(outcomeFeedback),
          })
        );
        console.log(`[Act] Sent outcome feedback to Think service for learning`);
      } catch (thinkErr: any) {
        console.warn(`[Act] Outcome feedback to Think failed: ${thinkErr.message}`);
        // Non-blocking - don't fail execution if learning fails
      }
    } else {
      console.warn(`[Act] THINK service not bound - cannot send outcome feedback`);
    }

    // 6. Update action metadata (NOT Spine truth - this is workflow state only)

    // Update Supabase with execution result
    try {
      await fetch(
        `${c.env.SUPABASE_URL}/rest/v1/actions?id=eq.${entityId}&tenant_id=eq.${tenantId}`,
        {
          method: "PATCH",
          headers: {
            apikey: c.env.SUPABASE_SERVICE_KEY,
            Authorization: `Bearer ${c.env.SUPABASE_SERVICE_KEY}`,
            "Content-Type": "application/json",
            Prefer: "return=minimal",
          },
          body: JSON.stringify({
            status: executionResult.success ? "executed" : "execution_failed",
            payload: { ...params, execution_result: executionResult },
          }),
        }
      );
    } catch {
      /* non-blocking */
    }

    // 6.5. ENGAGEMENT LOG: Record action execution as an engagement event
    // This closes the L2→L1 loop — approved actions appear in the account's engagement history.
    // Uses PostgREST schema routing (cs schema) for the engagement_log table.
    if (executionResult.success) {
      const entityId360 = proposal.spine_id || proposal.params?.entity_id || params?.entity_id;
      const entityName = params?.entity_name || proposal.params?.entity_name;
      if (entityId360) {
        try {
          await fetch(`${c.env.SUPABASE_URL}/rest/v1/engagement_log`, {
            method: "POST",
            headers: {
              apikey: c.env.SUPABASE_SERVICE_KEY,
              Authorization: `Bearer ${c.env.SUPABASE_SERVICE_KEY}`,
              "Content-Type": "application/json",
              Prefer: "return=minimal",
            },
            body: JSON.stringify({
              tenant_id: tenantId,
              account_id: entityId360,
              engagement_date: new Date().toISOString().split("T")[0],
              engagement_type: `AI Action: ${proposal.action_type || proposal.action_key || "unknown"}`,
              topics_discussed: proposal.title || `Executed action: ${proposal.action_type}`,
              action_items: executionResult.connector_result
                ? JSON.stringify(executionResult.connector_result)
                : null,
              sentiment: "neutral",
              next_steps: entityName
                ? `Follow up on ${proposal.action_type} for ${entityName}`
                : `Review execution outcome`,
            }),
          });
          console.log(`[Act] Wrote engagement_log entry for entity ${entityId360}`);
        } catch (engErr: any) {
          console.warn(`[Act] engagement_log write failed: ${engErr.message}`);
          // Non-blocking — don't fail execution if engagement logging fails
        }
      }
    }

    // 7. Audit trail
    try {
      await c.env.DB.prepare(
        `
                INSERT INTO audit_logs (id, tenant_id, actor_id, actor_type, action, entity_type, entity_id, metadata)
                VALUES (?, ?, 'act-engine', 'engine', 'execution_completed', ?, ?, ?)
            `
      )
        .bind(crypto.randomUUID(), tenantId, source, entityId, JSON.stringify(executionResult))
        .run();
    } catch {
      /* non-blocking */
    }

    return c.json(executionResult);
  } catch (err: any) {
    return c.json({ error: "Execution failed", message: err.message }, 500);
  }
});

/**
 * Get Action Proposals for a Situation
 * v3.6: Query from Supabase (truth database)
 */
app.get("/proposals/:situation_id", async (c) => {
  const situationId = c.req.param("situation_id");

  // Query Supabase (truth database)
  const results = await supabaseQuery(
    c.env.SUPABASE_URL,
    c.env.SUPABASE_SERVICE_KEY,
    "action_proposals",
    `situation_id=eq.${situationId}&order=proposal_rank.asc`
  );

  return c.json({ success: true, data: results });
});

export default app;
